insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values ('chat-media','chat-media',false,10485760,array['image/png','image/jpeg','image/webp','image/gif']) on conflict(id) do update set public=false,file_size_limit=excluded.file_size_limit,allowed_mime_types=excluded.allowed_mime_types;
create policy chat_media_read on storage.objects for select to authenticated using(bucket_id='chat-media' and (select private.verified_portal_session()) and (storage.foldername(name))[1]=any(private.shared_chat_divisions()) and (storage.foldername(name))[2] in ('general','deals','resources'));
create policy chat_media_upload on storage.objects for insert to authenticated with check(bucket_id='chat-media' and (select private.verified_portal_session()) and (storage.foldername(name))[1]=any(private.shared_chat_divisions()) and (storage.foldername(name))[2] in ('general','deals','resources') and (storage.foldername(name))[3]=(select auth.uid())::text);